-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        vehicle_id,
        meridex_fund_id,
        parent_vehicle_id,
        vehicle_name,
        vehicle_type,
        jurisdiction,
        incorporation_date,
        vehicle_lei,
        violation_00,
        violation_01
    from {{ ref("investment__meridex_legal_vehicle__checked") }}
),
violations as (
    select
        'vehicle_id_not_null' as rule_name,
        vehicle_id,
        meridex_fund_id,
        parent_vehicle_id,
        vehicle_name,
        vehicle_type,
        jurisdiction,
        incorporation_date,
        vehicle_lei
    from quarantined
    where violation_00

    union all

    select
        'vehicle_name_not_null' as rule_name,
        vehicle_id,
        meridex_fund_id,
        parent_vehicle_id,
        vehicle_name,
        vehicle_type,
        jurisdiction,
        incorporation_date,
        vehicle_lei
    from quarantined
    where violation_01
)

select
    rule_name,
    vehicle_id,
    meridex_fund_id,
    parent_vehicle_id,
    vehicle_name,
    vehicle_type,
    jurisdiction,
    incorporation_date,
    vehicle_lei
from violations
